line:
import { LineChart } from "@/components/charts/line-chart";

const data = [{ month: "Jan", sales: 120 }, { month: "Feb", sales: 180 }];
const config = { sales: { label: "Sales", color: "#733bff" } };

export function Dashboard() {
  return <LineChart data={data} config={config} xDataKey="month" aria-label="Monthly sales" />;
}

heatmap:
import { HeatmapChart, createHeatmapScale } from "@/components/charts/heatmap-chart";

const data = [{ row: "Mon", column: "AM", value: 12 }];
const scale = createHeatmapScale({ domain: [0, 20], colors: ["#eff6ff", "#2563eb"] });

export function Dashboard() {
  return <HeatmapChart rows={["Mon"]} columns={["AM"]} data={data} scale={scale} aria-label="Requests by shift" />;
}

